package local.proskurnin.preview;
import android.content.*;import android.media.*;import android.os.*;import android.util.*;import java.io.*;import java.util.concurrent.*;import java.util.function.BooleanSupplier;import org.json.*;
/** Foreground-only speech output. No provider key or persistent audio files. */
final class SpeechPlayback {
 interface Listener {void state(String value);}
 final Context context;final Handler handler=new Handler();final ExecutorService worker=Executors.newSingleThreadExecutor();final BooleanSupplier allowed;final Listener listener;final AudioManager audio;
 MediaPlayer player;AudioFocusRequest focus;File file;CancellationSignal cancel;int generation=0;boolean active=false,closed=false;
 SpeechPlayback(Context c,BooleanSupplier a,Listener l){context=c;allowed=a;listener=l;audio=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);}
 void play(String id){stop();if(closed||!allowed.getAsBoolean())return;final int token=generation;active=true;listener.state("loading");final CancellationSignal signal=new CancellationSignal();cancel=signal;
  worker.execute(()->{File downloaded=null;String failure=null;try{JSONObject result=ApiClient.request(context,"ai/speech",new JSONObject().put("speech_id",id),signal);signal.throwIfCanceled();if(!"audio/mpeg".equals(result.optString("mime")))throw new IOException("FORMAT");byte[] bytes=Base64.decode(result.getString("audio_base64"),Base64.DEFAULT);if(bytes.length<128||bytes.length>1048576)throw new IOException("LIMIT");downloaded=File.createTempFile("ai-speech-",".mp3",context.getCacheDir());try(FileOutputStream out=new FileOutputStream(downloaded)){out.write(bytes);}signal.throwIfCanceled();}catch(Exception e){failure="speech_expired".equals(e.getMessage())?"expired":"error";}final File ready=downloaded;final String error=failure;handler.post(()->{if(closed||token!=generation||!allowed.getAsBoolean()){if(ready!=null)ready.delete();return;}cancel=null;if(error!=null){if(ready!=null)ready.delete();stop();listener.state(error);return;}file=ready;prepare(token);});});
 }
 void prepare(int token){try{player=new MediaPlayer();AudioAttributes attributes=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ASSISTANT).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build();player.setAudioAttributes(attributes);player.setDataSource(file.getAbsolutePath());player.setOnPreparedListener(mp->{if(token!=generation||!allowed.getAsBoolean()){stop();return;}focus=new AudioFocusRequest.Builder(AudioManager.AUDIOFOCUS_GAIN_TRANSIENT).setAudioAttributes(attributes).setOnAudioFocusChangeListener(change->{if(change<0)stop();},handler).build();if(audio.requestAudioFocus(focus)!=AudioManager.AUDIOFOCUS_REQUEST_GRANTED){stop();listener.state("focus");return;}mp.start();listener.state("playing");Log.i("ProskurninSpeech","playing duration_ms="+mp.getDuration());});player.setOnCompletionListener(mp->{if(token==generation){Log.i("ProskurninSpeech","completed");stop();listener.state("completed");}});player.setOnErrorListener((mp,what,extra)->{if(token==generation){stop();listener.state("error");}return true;});player.prepareAsync();}catch(Exception e){stop();listener.state("error");}}
 void stop(){generation++;active=false;if(cancel!=null){CancellationSignal old=cancel;cancel=null;old.cancel();}if(player!=null){player.release();player=null;}if(focus!=null){audio.abandonAudioFocusRequest(focus);focus=null;}if(file!=null){file.delete();file=null;}listener.state("idle");}
 void close(){closed=true;stop();worker.shutdownNow();}
}
